create or replace semantic view SALES_METRICS
	tables (
		CSA.TJ.ORDER_FACT primary key (ORDER_ID,ORDER_LINE,RETURN_DATE_KEY),
		CSA.TJ.CUSTOMER_DIM primary key (CUSTOMER_KEY),
		CSA.TJ.PRODUCT_DIM primary key (PRODUCT_KEY),
		CSA.TJ.STORE_DIM primary key (STORE_KEY),
		CSA.TJ.DATE_DIM primary key (DATE_KEY),
		CSA.TJ.PROMO_DIM primary key (PROMO_KEY)
	)
	relationships (
		ORDER_FACT_TO_CUSTOMER_DIM as ORDER_FACT(CUSTOMER_KEY) references CUSTOMER_DIM(CUSTOMER_KEY),
		ORDER_FACT_TO_DATE_DIM as ORDER_FACT(ORDER_DATE_KEY) references DATE_DIM(DATE_KEY),
		ORDER_FACT_TO_PRODUCT_DIM as ORDER_FACT(PRODUCT_KEY) references PRODUCT_DIM(PRODUCT_KEY),
		ORDER_FACT_TO_PROMO_DIM as ORDER_FACT(PROMO_KEY) references PROMO_DIM(PROMO_KEY),
		ORDER_FACT_TO_STORE_DIM as ORDER_FACT(ORDER_STORE_KEY) references STORE_DIM(STORE_KEY)
	)
	facts (
		ORDER_FACT.UNIT_PRICE as UNIT_PRICE,
		ORDER_FACT.UNIT_COST as UNIT_COST,
		ORDER_FACT.DISCOUNT_AMOUNT as DISCOUNT_AMOUNT,
		ORDER_FACT.SHIPPING_AMOUNT as SHIPPING_AMOUNT,
		ORDER_FACT.TAX_AMOUNT as TAX_AMOUNT,
		ORDER_FACT.GROSS_REVENUE as GROSS_REVENUE,
		ORDER_FACT.NET_REVENUE as NET_REVENUE,
		ORDER_FACT.GROSS_PROFIT as GROSS_PROFIT,
		ORDER_FACT.NET_PROFIT as NET_PROFIT,
		ORDER_FACT.IS_RETURNED as IS_RETURNED,
		CUSTOMER_DIM.LIFETIME_ORDER_COUNT as LIFETIME_ORDER_COUNT,
		PRODUCT_DIM.UNIT_COST as UNIT_COST,
		PRODUCT_DIM.UNIT_PRICE as UNIT_PRICE,
		PRODUCT_DIM.WEIGHT_LBS as WEIGHT_LBS,
		PRODUCT_DIM.IS_ACTIVE as IS_ACTIVE,
		STORE_DIM.SQUARE_FOOTAGE as SQUARE_FOOTAGE,
		STORE_DIM.HAS_CURBSIDE as HAS_CURBSIDE,
		STORE_DIM.ANNUAL_LEASE_COST as ANNUAL_LEASE_COST,
		DATE_DIM.IS_WEEKEND as IS_WEEKEND,
		PROMO_DIM.DISCOUNT_PCT as DISCOUNT_PCT,
		PROMO_DIM.MIN_ORDER_AMOUNT as MIN_ORDER_AMOUNT,
		PROMO_DIM.PROMO_COST as PROMO_COST
	)
	dimensions (
		ORDER_FACT.ORDER_ID as ORDER_ID,
		ORDER_FACT.ORDER_LINE as ORDER_LINE,
		ORDER_FACT.CUSTOMER_KEY as CUSTOMER_KEY,
		ORDER_FACT.PRODUCT_KEY as PRODUCT_KEY,
		ORDER_FACT.ORDER_STORE_KEY as ORDER_STORE_KEY,
		ORDER_FACT.SHIP_STORE_KEY as SHIP_STORE_KEY,
		ORDER_FACT.PROMO_KEY as PROMO_KEY,
		ORDER_FACT.ORDER_DATE_KEY as ORDER_DATE_KEY,
		ORDER_FACT.SHIP_DATE_KEY as SHIP_DATE_KEY,
		ORDER_FACT.RETURN_DATE_KEY as RETURN_DATE_KEY,
		ORDER_FACT.ORDER_CHANNEL as ORDER_CHANNEL,
		ORDER_FACT.SHIP_METHOD as SHIP_METHOD,
		ORDER_FACT.ORDER_STATUS as ORDER_STATUS,
		ORDER_FACT.QUANTITY_ORDERED as QUANTITY_ORDERED,
		ORDER_FACT.QUANTITY_RETURNED as QUANTITY_RETURNED,
		ORDER_FACT.IS_FIRST_ORDER as IS_FIRST_ORDER,
		ORDER_FACT.IS_CANCELLED as IS_CANCELLED,
		ORDER_FACT.DAYS_TO_SHIP as DAYS_TO_SHIP,
		CUSTOMER_DIM.CUSTOMER_KEY as CUSTOMER_KEY,
		CUSTOMER_DIM.CUSTOMER_ID as CUSTOMER_ID,
		CUSTOMER_DIM.FIRST_NAME as FIRST_NAME,
		CUSTOMER_DIM.LAST_NAME as LAST_NAME,
		CUSTOMER_DIM.EMAIL as EMAIL,
		CUSTOMER_DIM.PHONE as PHONE,
		CUSTOMER_DIM.CITY as CITY,
		CUSTOMER_DIM.STATE as STATE,
		CUSTOMER_DIM.ZIP_CODE as ZIP_CODE,
		CUSTOMER_DIM.REGION as REGION,
		CUSTOMER_DIM.CUSTOMER_SEGMENT as CUSTOMER_SEGMENT,
		CUSTOMER_DIM.LOYALTY_TIER as LOYALTY_TIER,
		CUSTOMER_DIM.ACQUISITION_CHANNEL as ACQUISITION_CHANNEL,
		CUSTOMER_DIM.IS_ACTIVE as IS_ACTIVE,
		CUSTOMER_DIM.IS_EMAIL_OPT_IN as IS_EMAIL_OPT_IN,
		CUSTOMER_DIM.LIFETIME_REVENUE as LIFETIME_REVENUE,
		CUSTOMER_DIM.FIRST_ORDER_DATE as FIRST_ORDER_DATE,
		PRODUCT_DIM.PRODUCT_KEY as PRODUCT_KEY,
		PRODUCT_DIM.PRODUCT_ID as PRODUCT_ID,
		PRODUCT_DIM.PRODUCT_NAME as PRODUCT_NAME,
		PRODUCT_DIM.CATEGORY as CATEGORY,
		PRODUCT_DIM.SUBCATEGORY as SUBCATEGORY,
		PRODUCT_DIM.BRAND as BRAND,
		PRODUCT_DIM.IS_PRIVATE_LABEL as IS_PRIVATE_LABEL,
		PRODUCT_DIM.IS_SEASONAL as IS_SEASONAL,
		PRODUCT_DIM.LAUNCH_DATE as LAUNCH_DATE,
		PRODUCT_DIM.DISCONTINUE_DATE as DISCONTINUE_DATE,
		STORE_DIM.STORE_KEY as STORE_KEY,
		STORE_DIM.STORE_ID as STORE_ID,
		STORE_DIM.STORE_NAME as STORE_NAME,
		STORE_DIM.STORE_TYPE as STORE_TYPE,
		STORE_DIM.CITY as CITY,
		STORE_DIM.STATE as STATE,
		STORE_DIM.REGION as REGION,
		STORE_DIM.DISTRICT as DISTRICT,
		STORE_DIM.IS_ACTIVE as IS_ACTIVE,
		STORE_DIM.HAS_CAFE as HAS_CAFE,
		STORE_DIM.MANAGER_NAME as MANAGER_NAME,
		STORE_DIM.STORE_PHONE as STORE_PHONE,
		STORE_DIM.OPEN_DATE as OPEN_DATE,
		STORE_DIM.CLOSE_DATE as CLOSE_DATE,
		DATE_DIM.DATE_KEY as DATE_KEY,
		DATE_DIM.DAY_OF_WEEK as DAY_OF_WEEK,
		DATE_DIM.DAY_OF_MONTH as DAY_OF_MONTH,
		DATE_DIM.WEEK_OF_YEAR as WEEK_OF_YEAR,
		DATE_DIM.MONTH_NUMBER as MONTH_NUMBER,
		DATE_DIM.MONTH_NAME as MONTH_NAME,
		DATE_DIM.QUARTER as QUARTER,
		DATE_DIM.YEAR as YEAR,
		DATE_DIM.IS_HOLIDAY as IS_HOLIDAY,
		DATE_DIM.FISCAL_PERIOD as FISCAL_PERIOD,
		DATE_DIM.FULL_DATE as FULL_DATE,
		PROMO_DIM.PROMO_KEY as PROMO_KEY,
		PROMO_DIM.PROMO_ID as PROMO_ID,
		PROMO_DIM.PROMO_NAME as PROMO_NAME,
		PROMO_DIM.PROMO_TYPE as PROMO_TYPE,
		PROMO_DIM.CHANNEL as CHANNEL,
		PROMO_DIM.IS_STACKABLE as IS_STACKABLE,
		PROMO_DIM.TARGET_SEGMENT as TARGET_SEGMENT,
		PROMO_DIM.START_DATE as START_DATE,
		PROMO_DIM.END_DATE as END_DATE
	)
	metrics (
		ORDER_FACT.TOTAL_GROSS_REVENUE as SUM(GROSS_REVENUE) comment='Total gross revenue from all orders',
		ORDER_FACT.TOTAL_NET_REVENUE as SUM(NET_REVENUE) comment='Total net revenue after discounts and returns',
		ORDER_FACT.TOTAL_GROSS_PROFIT as SUM(GROSS_PROFIT) comment='Total gross profit from all orders',
		ORDER_FACT.TOTAL_NET_PROFIT as SUM(NET_PROFIT) comment='Total net profit after all costs',
		ORDER_FACT.TOTAL_ORDERS as COUNT(DISTINCT ORDER_ID) comment='Total number of unique orders',
		ORDER_FACT.TOTAL_QUANTITY_ORDERED as SUM(QUANTITY_ORDERED) comment='Total units ordered',
		ORDER_FACT.TOTAL_QUANTITY_RETURNED as SUM(QUANTITY_RETURNED) comment='Total units returned',
		ORDER_FACT.TOTAL_DISCOUNT as SUM(DISCOUNT_AMOUNT) comment='Total discount amount given',
		ORDER_FACT.TOTAL_SHIPPING as SUM(SHIPPING_AMOUNT) comment='Total shipping costs',
		ORDER_FACT.TOTAL_TAX as SUM(TAX_AMOUNT) comment='Total tax collected',
		ORDER_FACT.AVG_ORDER_VALUE as AVG(GROSS_REVENUE) comment='Average order value per order line',
		ORDER_FACT.RETURN_RATE as SUM(QUANTITY_RETURNED) / NULLIF(SUM(QUANTITY_ORDERED), 0) comment='Ratio of units returned to units ordered',
		ORDER_FACT.PROFIT_MARGIN as SUM(NET_PROFIT) / NULLIF(SUM(NET_REVENUE), 0) comment='Net profit margin ratio',
		ORDER_FACT.AVG_DAYS_TO_SHIP as AVG(DAYS_TO_SHIP) comment='Average days between order and shipment'
	)
	comment='Sales analytics model with metrics for revenue, profit, orders, and returns across customers, products, stores, dates, and promotions.'
	with extension (CA='{"tables":[{"name":"ORDER_FACT","dimensions":[{"name":"ORDER_ID"},{"name":"ORDER_LINE"},{"name":"CUSTOMER_KEY"},{"name":"PRODUCT_KEY"},{"name":"ORDER_STORE_KEY"},{"name":"SHIP_STORE_KEY"},{"name":"PROMO_KEY"},{"name":"ORDER_DATE_KEY"},{"name":"SHIP_DATE_KEY"},{"name":"RETURN_DATE_KEY"},{"name":"ORDER_CHANNEL"},{"name":"SHIP_METHOD"},{"name":"ORDER_STATUS"},{"name":"QUANTITY_ORDERED"},{"name":"QUANTITY_RETURNED"},{"name":"IS_FIRST_ORDER"},{"name":"IS_CANCELLED"},{"name":"DAYS_TO_SHIP"}],"facts":[{"name":"UNIT_PRICE"},{"name":"UNIT_COST"},{"name":"DISCOUNT_AMOUNT"},{"name":"SHIPPING_AMOUNT"},{"name":"TAX_AMOUNT"},{"name":"GROSS_REVENUE"},{"name":"NET_REVENUE"},{"name":"GROSS_PROFIT"},{"name":"NET_PROFIT"},{"name":"IS_RETURNED"}],"metrics":[{"name":"TOTAL_GROSS_REVENUE"},{"name":"TOTAL_NET_REVENUE"},{"name":"TOTAL_GROSS_PROFIT"},{"name":"TOTAL_NET_PROFIT"},{"name":"TOTAL_ORDERS"},{"name":"TOTAL_QUANTITY_ORDERED"},{"name":"TOTAL_QUANTITY_RETURNED"},{"name":"TOTAL_DISCOUNT"},{"name":"TOTAL_SHIPPING"},{"name":"TOTAL_TAX"},{"name":"AVG_ORDER_VALUE"},{"name":"RETURN_RATE"},{"name":"PROFIT_MARGIN"},{"name":"AVG_DAYS_TO_SHIP"}],"foreign_keys":[{"fkey_columns":["CUSTOMER_KEY"],"pkey_table":{"database":"CSA","schema":"TJ","table":"CUSTOMER_DIM"},"pkey_columns":["CUSTOMER_KEY"]},{"fkey_columns":["ORDER_DATE_KEY"],"pkey_table":{"database":"CSA","schema":"TJ","table":"DATE_DIM"},"pkey_columns":["DATE_KEY"]},{"fkey_columns":["SHIP_DATE_KEY"],"pkey_table":{"database":"CSA","schema":"TJ","table":"DATE_DIM"},"pkey_columns":["DATE_KEY"]},{"fkey_columns":["RETURN_DATE_KEY"],"pkey_table":{"database":"CSA","schema":"TJ","table":"DATE_DIM"},"pkey_columns":["DATE_KEY"]},{"fkey_columns":["PRODUCT_KEY"],"pkey_table":{"database":"CSA","schema":"TJ","table":"PRODUCT_DIM"},"pkey_columns":["PRODUCT_KEY"]},{"fkey_columns":["PROMO_KEY"],"pkey_table":{"database":"CSA","schema":"TJ","table":"PROMO_DIM"},"pkey_columns":["PROMO_KEY"]},{"fkey_columns":["ORDER_STORE_KEY"],"pkey_table